import{_ as t}from"./chunks/console-tenants.DGEJUwWF.js";import{_ as a,o as n,c as s,a3 as r}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Manage tenants","description":"Manage tenants - create, edit, deactivate, and manage the member roster of a tenant in the Console.","frontmatter":{"description":"Manage tenants - create, edit, deactivate, and manage the member roster of a tenant in the Console."},"headers":[],"relativePath":"how-to/console/tenants.md","filePath":"how-to/console/tenants.md"}'),o={name:"how-to/console/tenants.md"};function i(l,e,h,d,c,p){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="manage-tenants" tabindex="-1">Manage tenants <a class="header-anchor" href="#manage-tenants" aria-label="Permalink to &quot;Manage tenants&quot;">​</a></h1><p>Tenants are your customer organizations inside your ShipperDog organization — the teams your releases target. The <strong>Tenants</strong> screen in the Console lists them all; each tenant row opens its member roster, device registry, and tenant dashboard.</p><p><img src="'+t+'" alt="The Tenants screen"></p><p>Why tenants exist as a boundary is covered in <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a>.</p><h2 id="create-a-tenant" tabindex="-1">Create a tenant <a class="header-anchor" href="#create-a-tenant" aria-label="Permalink to &quot;Create a tenant&quot;">​</a></h2><ol><li><p>Open <strong>Tenants</strong> in the navigation drawer.</p></li><li><p>Click <strong>New tenant</strong>.</p></li><li><p>Fill in the dialog:</p><ul><li><strong>Name</strong> — the tenant&#39;s display name (1–200 characters).</li><li><strong>External ID</strong> — the globally unique mapping to your customer system (1–100 characters). This is the identifier your billing or CRM uses; it can never collide with another tenant&#39;s.</li></ul></li><li><p>Click <strong>Create</strong>. The tenant appears in the grid as <strong>Active</strong>.</p></li></ol><h2 id="find-and-edit-tenants" tabindex="-1">Find and edit tenants <a class="header-anchor" href="#find-and-edit-tenants" aria-label="Permalink to &quot;Find and edit tenants&quot;">​</a></h2><ul><li><strong>Search</strong> filters the loaded rows by name or external ID; <strong>Status</strong> narrows to Active or Deactivated tenants. Large lists page through <strong>Load more</strong>.</li><li><strong>Edit</strong> on a row reopens the same dialog to rename the tenant or correct its external ID.</li></ul><h2 id="deactivate-and-reactivate" tabindex="-1">Deactivate and reactivate <a class="header-anchor" href="#deactivate-and-reactivate" aria-label="Permalink to &quot;Deactivate and reactivate&quot;">​</a></h2><p>Tenants are never deleted — deactivation is the reversible parking move:</p><ol><li>Click <strong>Deactivate</strong> on the tenant&#39;s row.</li><li>Confirm in the dialog. Deactivation blocks new memberships but keeps all data, members, and applications.</li><li><strong>Reactivate</strong> (in the same place) reverses it whenever the customer returns.</li></ol><h2 id="manage-a-tenant-s-members" tabindex="-1">Manage a tenant&#39;s members <a class="header-anchor" href="#manage-a-tenant-s-members" aria-label="Permalink to &quot;Manage a tenant&#39;s members&quot;">​</a></h2><ol><li><p>Click <strong>Members</strong> on the tenant&#39;s row. The roster lists each member&#39;s email, name, role, and status.</p></li><li><p>Add a member with <strong>Add member</strong>: pick the user from your organization&#39;s member roster — or paste a raw user id for tenant testers who are not organization members — and choose the role:</p><ul><li><strong>Tenant Admin</strong> — manages the tenant: members, devices, and the tenant dashboard.</li><li><strong>Tenant Tester</strong> — sees the tenant&#39;s applications in the <a href="/shipperdog/snapshot/roles/tester">Tester Portal</a> and installs builds.</li></ul></li><li><p>Change a role with the <strong>Role</strong> selector on the row — it applies immediately.</p></li><li><p><strong>Suspend</strong> revokes a member&#39;s sessions at once (the row shows <strong>Suspended</strong>); <strong>Reactivate</strong> restores access. <strong>Remove</strong> takes the member out of the tenant with a confirmation.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Testers versus members</p><p>A tester who only installs builds needs no Console presence at all — invite them as a tester and they live entirely in the <a href="/shipperdog/snapshot/how-to/portal/accept-invite">Portal</a>. Add someone as a tenant <em>member</em> only when they need the tenant&#39;s Console views.</p></div><h2 id="the-per-tenant-screens" tabindex="-1">The per-tenant screens <a class="header-anchor" href="#the-per-tenant-screens" aria-label="Permalink to &quot;The per-tenant screens&quot;">​</a></h2><ul><li><strong>Devices</strong> opens the <a href="/shipperdog/snapshot/how-to/console/devices">device registry</a>.</li><li><strong>Dashboard</strong> opens the <a href="/shipperdog/snapshot/how-to/console/analytics-and-dashboards">tenant dashboard</a> — in-flight releases and the seven-day download trend for that tenant.</li></ul><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/devices">manage devices</a> · <a href="/shipperdog/snapshot/how-to/console/orgs">onboard an organization</a> · <a href="/shipperdog/snapshot/roles/tenant-admin">tenant-admin quickstart</a></p>',17)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
